 417→    fn make_probe() -> EnvironmentProbe {
 418→        EnvironmentProbe::run_with_env(|_| Err(std::env::VarError::NotPresent))
 419→    }
 420→
 421→    fn stub_ctx(command_succeeds: bool, network_ok: bool) -> InstallerContext<'static> {
 422→        let run_cmd: &'static dyn Fn(&str) -> bool = if command_succeeds {
 423→            &|_| true
 424→        } else {
 425→            &|_| false
 426→        };
 427→        let net: &'static dyn Fn() -> bool = if network_ok { &|| true } else { &|| false };
 428→        InstallerContext {
 429→            run_command: run_cmd,
 430→            check_network: net,
 431→            prepend_path: &|_| {},
 432→        }
 433→    }
 434→
 435→    fn make_checker<'a>(
 436→        registry: &'a RequirementRegistry,
 437→        probe: &'a EnvironmentProbe,
 438→        temp: &TempDir,
 439→    ) -> GapChecker<'a> {
 440→        GapChecker::new(registry, probe, temp.path())
 441→    }
