 615→    // --- 6C: Missing tests ---
 616→
 617→    #[test]
 618→    fn missing_prompts_install() {
 619→        let registry = RequirementRegistry::new();
 620→        let probe = make_probe();
 621→        let temp = TempDir::new().unwrap();
 622→        let mut checker = make_checker(&registry, &probe, &temp);
 623→        let mut ui = MockUI::new();
 624→        ui.set_interactive(true);
 625→        ui.set_prompt_response("install_mise", "yes");
 626→        ui.set_prompt_response("install_ruby", "yes");
 627→        let ctx = stub_ctx(true, true);
 628→
 629→        let gaps = vec![GapResult {
 630→            requirement: "ruby".to_string(),
 631→            status: RequirementStatus::Missing {
 632→                install_template: Some("mise-ruby".to_string()),
 633→                install_hint: Some("Install Ruby via mise".to_string()),
 634→            },
 635→        }];
