 1→//! Bivvy CLI entry point.
 2→
 3→use std::process::ExitCode;
 4→
 5→use bivvy::cli::{Cli, CommandDispatcher, Commands};
 6→use bivvy::shell::is_ci;
 7→use bivvy::ui::{create_ui, OutputMode};
 8→use clap::Parser;
 9→use tracing_subscriber::{fmt, prelude::*, EnvFilter};
10→
11→/// Initialize the tracing subscriber for logging.
12→///
13→/// Log level is controlled by:
14→/// 1. `--debug` flag sets level to DEBUG
15→/// 2. `RUST_LOG` environment variable (if set)
16→/// 3. Default is INFO
17→fn init_tracing(debug: bool) {
18→    let filter = if debug {
19→        EnvFilter::new("bivvy=debug")
20→    } else {
21→        EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("bivvy=info"))
22→    };
23→
24→    tracing_subscriber::registry()
25→        .with(fmt::layer().with_target(false))
26→        .with(filter)
27→        .init();
28→}
29→
30→fn main() -> ExitCode {
31→    let cli = Cli::parse();
32→    init_tracing(cli.debug);
33→
34→    tracing::debug!("Bivvy starting with args: {:?}", cli);
35→
36→    // Determine output mode
37→    let output_mode = if cli.quiet {
38→        OutputMode::Quiet
39→    } else if cli.verbose {
40→        OutputMode::Verbose
41→    } else {
42→        OutputMode::Normal
43→    };
44→
45→    // Handle --no-color
46→    if cli.no_color {
47→        std::env::set_var("NO_COLOR", "1");
48→    }
49→
50→    // Determine project root
51→    let project_root = cli
52→        .project
53→        .as_ref()
54→        .cloned()
55→        .unwrap_or_else(|| std::env::current_dir().unwrap_or_default());
56→
57→    // Check if non-interactive (CI mode or explicit flag)
58→    let is_interactive = match &cli.command {
59→        Some(Commands::Run(args)) => !args.non_interactive && !args.ci && !is_ci(),
60→        _ => !is_ci(),
61→    };
62→
63→    // Create UI
64→    let mut ui = create_ui(is_interactive, output_mode);
65→
66→    // Dispatch command
67→    let dispatcher = CommandDispatcher::new(project_root);
68→
69→    match dispatcher.dispatch(&cli, ui.as_mut()) {
70→        Ok(result) => ExitCode::from(result.exit_code as u8),
71→        Err(e) => {
72→            ui.error(&format!("Error: {}", e));
73→            ExitCode::from(1)
74→        }
75→    }
76→}
