  1→//! Cache validation and invalidation logic.
  2→
  3→use anyhow::Result;
  4→use chrono::{Duration, Utc};
  5→
  6→use super::{CacheEntry, CacheStore};
  7→use crate::registry::source::RemoteCacheStrategy;
  8→
  9→/// Cache validator for checking entry freshness.
 10→pub struct CacheValidator<'a> {
 11→    store: &'a CacheStore,
 12→}
 13→
 14→/// Result of cache validation.
 15→#[derive(Debug, Clone, PartialEq, Eq)]
 16→pub enum ValidationResult {
 17→    /// Entry is fresh and valid.
 18→    Fresh,
 19→    /// Entry expired (TTL).
 20→    Expired,
 21→    /// Entry needs revalidation (ETag/git check).
 22→    NeedsRevalidation,
 23→    /// Entry not found.
 24→    NotFound,
 25→}
 26→
 27→impl<'a> CacheValidator<'a> {
 28→    /// Create a new cache validator.
 29→    pub fn new(store: &'a CacheStore) -> Self {
 30→        Self { store }
 31→    }
 32→
 33→    /// Validate a cache entry based on strategy.
 34→    pub fn validate(
 35→        &self,
 36→        source_id: &str,
 37→        template_name: &str,
 38→        strategy: RemoteCacheStrategy,
 39→    ) -> Result<ValidationResult> {
 40→        let entry = match self.store.load(source_id, template_name)? {
 41→            Some(e) => e,
 42→            None => return Ok(ValidationResult::NotFound),
 43→        };
 44→
 45→        match strategy {
 46→            RemoteCacheStrategy::Ttl => self.validate_ttl(&entry),
 47→            RemoteCacheStrategy::Etag => self.validate_etag(&entry),
 48→            RemoteCacheStrategy::Git => self.validate_git(&entry),
 49→        }
 50→    }
 51→
 52→    /// Validate using TTL only.
 53→    fn validate_ttl(&self, entry: &CacheEntry) -> Result<ValidationResult> {
 54→        if entry.is_expired() {
 55→            Ok(ValidationResult::Expired)
 56→        } else {
 57→            Ok(ValidationResult::Fresh)
 58→        }
 59→    }
 60→
 61→    /// Validate with ETag strategy.
 62→    ///
 63→    /// If TTL expired, needs revalidation via HTTP.
 64→    fn validate_etag(&self, entry: &CacheEntry) -> Result<ValidationResult> {
 65→        if entry.is_expired() {
 66→            if entry.metadata.etag.is_some() {
 67→                Ok(ValidationResult::NeedsRevalidation)
 68→            } else {
 69→                Ok(ValidationResult::Expired)
 70→            }
 71→        } else {
 72→            Ok(ValidationResult::Fresh)
 73→        }
 74→    }
 75→
 76→    /// Validate with git strategy.
 77→    ///
 78→    /// If TTL expired, needs revalidation via git.
 79→    fn validate_git(&self, entry: &CacheEntry) -> Result<ValidationResult> {
 80→        if entry.is_expired() {
 81→            if entry.metadata.commit_sha.is_some() {
 82→                Ok(ValidationResult::NeedsRevalidation)
 83→            } else {
 84→                Ok(ValidationResult::Expired)
 85→            }
 86→        } else {
 87→            Ok(ValidationResult::Fresh)
 88→        }
 89→    }
 90→
 91→    /// Clean up expired entries (TTL-only cleanup).
 92→    pub fn cleanup_expired(&self) -> Result<usize> {
 93→        let entries = self.store.list()?;
 94→        let mut removed = 0;
 95→
 96→        for entry in entries {
 97→            if entry.is_expired() && self.store.remove(&entry.source_id, &entry.template_name)? {
 98→                removed += 1;
 99→            }
100→        }
101→
102→        Ok(removed)
103→    }
104→
105→    /// Get entries older than a duration.
106→    pub fn entries_older_than(&self, age: Duration) -> Result<Vec<CacheEntry>> {
107→        let entries = self.store.list()?;
108→        let cutoff = Utc::now() - age;
109→
110→        Ok(entries
111→            .into_iter()
112→            .filter(|e| e.metadata.cached_at < cutoff)
113→            .collect())
114→    }
115→}
116→
117→/// Parse a TTL string like "7d", "24h", "30m".
118→pub fn parse_ttl(ttl: &str) -> Result<Duration> {
119→    let ttl = ttl.trim().to_lowercase();
120→
121→    if let Some(days) = ttl.strip_suffix('d') {
122→        let n: i64 = days.parse()?;
123→        Ok(Duration::days(n))
124→    } else if let Some(hours) = ttl.strip_suffix('h') {
125→        let n: i64 = hours.parse()?;
126→        Ok(Duration::hours(n))
127→    } else if let Some(mins) = ttl.strip_suffix('m') {
128→        let n: i64 = mins.parse()?;
129→        Ok(Duration::minutes(n))
130→    } else if let Some(secs) = ttl.strip_suffix('s') {
131→        let n: i64 = secs.parse()?;
132→        Ok(Duration::seconds(n))
133→    } else {
134→        // Assume seconds if no suffix
135→        let n: i64 = ttl.parse()?;
136→        Ok(Duration::seconds(n))
137→    }
138→}
139→
140→/// Format a duration for display.
141→pub fn format_duration(duration: Duration) -> String {
142→    let secs = duration.num_seconds();
143→
144→    if secs >= 86400 {
145→        let days = secs / 86400;
146→        format!("{}d", days)
147→    } else if secs >= 3600 {
148→        let hours = secs / 3600;
149→        format!("{}h", hours)
150→    } else if secs >= 60 {
151→        let mins = secs / 60;
152→        format!("{}m", mins)
153→    } else {
154→        format!("{}s", secs)
155→    }
156→}
